describe('File Upload Error Handling', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should display an error message for unsupported file type', () => {
        const fileName = 'unsupported-file.txt'; // Example of an unsupported file type
        cy.get('input[type="file"]').attachFile(fileName);
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('be.visible').and('contain', 'Unsupported file type');
    });

    it('should not display an error message for supported file type', () => {
        const fileName = 'supported-file.pdf'; // Example of a supported file type
        cy.get('input[type="file"]').attachFile(fileName);
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('not.exist');
    });
});
